#include <iostream>
using namespace std;
int fi(int n)
{
    if(n==0)return 0;
    if(n==1)return 1;
    return fi(n-2)+fi(n-1);
}
int main() {
    int a,b;cin>>a>>b;
    int n=1,tong=0;
    while(fi(n)<b)
    {
        if(fi(n)>=a)tong=tong+fi(n);
        n++;
    }
    cout<<tong;
}

